CREATE TABLE semio_mesh_document (id INTEGER PRIMARY KEY, schema TEXT NOT NULL);
CREATE TABLE semio_mesh_mesh (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES semio_mesh_document(id), ordinal INTEGER NOT NULL CHECK (ordinal >= 0), native_id TEXT NOT NULL);
CREATE TABLE semio_mesh_primitive (id INTEGER PRIMARY KEY, mesh_id INTEGER NOT NULL REFERENCES semio_mesh_mesh(id), ordinal INTEGER NOT NULL CHECK (ordinal >= 0), native_id TEXT NOT NULL, topology TEXT NOT NULL CHECK (topology IN ('points','lines','line_strip','triangles','triangle_strip','triangle_fan')), material_id INTEGER REFERENCES semio_mesh_material(id));
CREATE TABLE semio_mesh_position (id INTEGER PRIMARY KEY, primitive_id INTEGER NOT NULL REFERENCES semio_mesh_primitive(id), ordinal INTEGER NOT NULL CHECK (ordinal >= 0), x REAL, y REAL, z REAL, x_ieee754_bits INTEGER, x_numeric_class TEXT, y_ieee754_bits INTEGER, y_numeric_class TEXT, z_ieee754_bits INTEGER, z_numeric_class TEXT);
CREATE TABLE semio_mesh_normal (id INTEGER PRIMARY KEY, primitive_id INTEGER NOT NULL REFERENCES semio_mesh_primitive(id), ordinal INTEGER NOT NULL CHECK (ordinal >= 0), x REAL, y REAL, z REAL, x_ieee754_bits INTEGER, x_numeric_class TEXT, y_ieee754_bits INTEGER, y_numeric_class TEXT, z_ieee754_bits INTEGER, z_numeric_class TEXT);
CREATE TABLE semio_mesh_uv (id INTEGER PRIMARY KEY, primitive_id INTEGER NOT NULL REFERENCES semio_mesh_primitive(id), ordinal INTEGER NOT NULL CHECK (ordinal >= 0), u REAL, v REAL, u_ieee754_bits INTEGER, u_numeric_class TEXT, v_ieee754_bits INTEGER, v_numeric_class TEXT);
CREATE TABLE semio_mesh_color (id INTEGER PRIMARY KEY, primitive_id INTEGER NOT NULL REFERENCES semio_mesh_primitive(id), ordinal INTEGER NOT NULL CHECK (ordinal >= 0), r REAL, g REAL, b REAL, a REAL, r_ieee754_bits INTEGER, r_numeric_class TEXT, g_ieee754_bits INTEGER, g_numeric_class TEXT, b_ieee754_bits INTEGER, b_numeric_class TEXT, a_ieee754_bits INTEGER, a_numeric_class TEXT);
CREATE TABLE semio_mesh_index (id INTEGER PRIMARY KEY, primitive_id INTEGER NOT NULL REFERENCES semio_mesh_primitive(id), ordinal INTEGER NOT NULL CHECK (ordinal >= 0), vertex_index INTEGER NOT NULL CHECK (vertex_index BETWEEN 0 AND 4294967295), position_id INTEGER NOT NULL REFERENCES semio_mesh_position(id));
CREATE TABLE semio_mesh_material (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES semio_mesh_document(id), ordinal INTEGER NOT NULL CHECK (ordinal >= 0), native_id TEXT NOT NULL, base_r REAL, base_g REAL, base_b REAL, base_a REAL, metallic REAL, roughness REAL, base_r_ieee754_bits INTEGER, base_r_numeric_class TEXT, base_g_ieee754_bits INTEGER, base_g_numeric_class TEXT, base_b_ieee754_bits INTEGER, base_b_numeric_class TEXT, base_a_ieee754_bits INTEGER, base_a_numeric_class TEXT, metallic_ieee754_bits INTEGER, metallic_numeric_class TEXT, roughness_ieee754_bits INTEGER, roughness_numeric_class TEXT);
CREATE TABLE semio_mesh_texture (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES semio_mesh_document(id), ordinal INTEGER NOT NULL CHECK (ordinal >= 0), native_id TEXT NOT NULL, mime TEXT NOT NULL, bytes BLOB NOT NULL);
